# Laufzeit-Teil: Spracherkennung, Wörterbuch, Muster, Links
def runtime(dic):
    import json
    return r"""
HB.EN=!!((window.Shopify&&String(Shopify.locale||'').indexOf('en')==0)||String(document.documentElement.lang||'').indexOf('en')==0);
HB.R=(window.Shopify&&Shopify.routes&&Shopify.routes.root)||'/';
HB.D=""" + json.dumps(dic, ensure_ascii=False) + r""";
HB.RX=[[/^Entspannt: Bestell bis (.+), dann ist es rechtzeitig da\.$/,'Relaxed: order by $1 and it will arrive in time.'],
[/^Bestell bis (.+), dann ist alles rechtzeitig da\. Noch (\d+) Tage\.$/,'Order by $1 and everything arrives in time. $2 days left.'],
[/^Jetzt bestellen! Noch (\d+) Tage? für die rechtzeitige Lieferung\.$/,'Order now! $1 day(s) left for on-time delivery.'],
[/^Jetzt bestellen! Nur noch (\d+) Tage? für pünktliche Lieferung\.$/,'Order now! Only $1 day(s) left for on-time delivery.'],
[/^Zum (\d+)\.$/,'For a $1th'],[/^ab (.+)$/,'from $1']];
HB.t=function(s){if(!HB.EN||!s)return s;var x=s.trim();if(!x)return s;if(HB.D[x]!=null)return s.replace(x,HB.D[x]);
var m=x.match(/^([^A-Za-zÄÖÜäöü0-9]+)(.+)$/);if(m&&HB.D[m[2]]!=null)return s.replace(x,m[1]+HB.D[m[2]]);
if(x.indexOf(' · ')>0)return s.replace(x,x.split(' · ').map(function(y){return HB.t(y);}).join(' · '));
var pre=m?m[1]:'',core=m?m[2]:x;for(var i=0;i<HB.RX.length;i++){if(HB.RX[i][0].test(core))return s.replace(x,pre+core.replace(HB.RX[i][0],HB.RX[i][1]));}return s;};
HB.link=function(el){if(HB.R=='/')return;el.querySelectorAll('a[href^="/"],form[action^="/"]').forEach(function(a){var at=a.tagName=='FORM'?'action':'href',v=a.getAttribute(at);if(v.indexOf(HB.R)!=0&&v.indexOf('/cdn')!=0)a.setAttribute(at,HB.R+v.slice(1));});};
HB.tr=function(el){HB.link(el);if(!HB.EN)return;var w=document.createTreeWalker(el,NodeFilter.SHOW_TEXT,null),n,L=[];while(n=w.nextNode())L.push(n);L.forEach(function(n){var t=HB.t(n.nodeValue);if(t!==n.nodeValue)n.nodeValue=t;});
el.querySelectorAll('[placeholder],[alt]').forEach(function(e){['placeholder','alt'].forEach(function(a){var v=e.getAttribute(a);if(v){var t=HB.t(v);if(t!==v)e.setAttribute(a,t);}});});};
HB.watch=function(el){HB.tr(el);new MutationObserver(function(ms){ms.forEach(function(m){m.addedNodes.forEach(function(n){if(n.nodeType==1)HB.tr(n);else if(n.nodeType==3){var t=HB.t(n.nodeValue);if(t!==n.nodeValue)n.nodeValue=t;}});});}).observe(el,{childList:true,subtree:true});};
"""
